code.java:
class Solution {
    public int countKeyChanges(String s){
        int changes=0;
        for(int i=1;i<s.length();i++)if(Character.toLowerCase(s.charAt(i))!=Character.toLowerCase(s.charAt(i-1)))changes++;
        return changes;
    }
}

code.kotlin:
class Solution {
    fun countKeyChanges(s:String):Int{
        var changes=0;
        for(i in 1 until s.length)if(s[i].lowercaseChar()!=s[i-1].lowercaseChar())changes++;
        return changes
    }
}

